    N, K, H = int(data[0]), int(data[1]), int(data[2])
    d = [int(x) for x in data[3:3 + N]]
    NEG = -1
    dp = [NEG] * (H + 2)
    dp[0] = 0
    for i in range(N):
        new = [NEG] * (H + 2)
        for r in range(0, min(i, H) + 1):
            v = dp[r]
            if v < 0:
                continue
            if r + 1 <= H and v > new[r + 1]:
                new[r + 1] = v
            if K + 2 * r - i >= 1:
                nv = v + d[i]
                if nv > new[r]:
                    new[r] = nv
        dp = new
    print(dp[H])

