    if bin(mask).count('1') != H:
        continue
    fuel = K
    total = 0
    ok = True
    for i in range(N):
        if mask >> i & 1:
            fuel += 1
        else:
            if fuel < 1:
                ok = False
                break
            fuel -= 1
            total += d[i]
    if ok and total > best:
        best = total
